'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numbers='一二三四五六七八',fields=['province','city','county','category','era','batch'];
const categories=['古建筑','古遗址','古墓葬','石窟寺及石刻','近现代重要史迹及代表性建筑','其他'],eras=['史前','夏商周','秦汉','魏晋南北朝','隋唐五代','宋辽金夏','元','明','清','近现代'];
const shortCategory=c=>c==='近现代重要史迹及代表性建筑'?'近现代史迹':c;
const state={rows:[],filtered:[],meta:null,china:null,chart:null,page:1,pageSize:20};
const collator=new Intl.Collator('zh-CN'),sortNames=a=>[...new Set(a)].sort(collator.compare);
function options(el,a,label){const old=el.value;el.innerHTML=`<option value="">${label}</option>`+a.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');el.value=a.includes(old)?old:'';}
function syncLocations(){const p=$('province').value,rows=state.rows.filter(r=>!p||r.province===p);options($('city'),p?sortNames(rows.map(r=>r.city)):[],'全部城市');$('city').disabled=!p;const c=$('city').value;options($('county'),c?sortNames(rows.filter(r=>r.city===c).map(r=>r.county)):[],'全部区县');$('county').disabled=!c;}
function filterRows(){const q=$('search').value.trim().toLocaleLowerCase();return state.rows.filter(r=>(!q||[r.name,r.address,r.province,r.city,r.county,r.era,...r.aliases||[]].join(' ').toLocaleLowerCase().includes(q))&&fields.every(f=>!$(f).value||(f==='era'?r.tags.includes($(f).value):String(r[f])===$(f).value)));}
function update(){state.page=1;state.filtered=filterRows();const count=state.filtered.length.toLocaleString();$('result-count').textContent=count;$('filter-count').textContent=count;const region=$('county').value||$('city').value||$('province').value||'全国';$('region-label').textContent=region;$('type-label').textContent=shortCategory($('category').value)||'全部类型';$('result-location').textContent=region==='全国'?'全国重点文物保护单位':['province','city','county'].map(f=>$(f).value).filter(Boolean).join(' · ');$('list-subtitle').textContent=`${region} · ${count} 条名录`;$('reset').hidden=!['search',...fields].some(f=>$(f).value);$('filter-dot').hidden=!['category','era','batch'].some(f=>$(f).value);const located=state.filtered.filter(r=>r.coordinates).length;$('map-hint').textContent=state.filtered.length===0?'没有匹配结果，试试其他关键词':!$('province').value?'轻点省份，发现历史':`${located} 处参考点位 · 轻点查看${state.filtered.length-located?' · '+(state.filtered.length-located)+' 处待定位':''}`;renderCards();renderMap();const url=new URL(location.href);url.hash='';for(const f of ['search',...fields]){const v=$(f).value;if(v)url.searchParams.set(f,v);else url.searchParams.delete(f);}history.replaceState(null,'',url);}
function reset(){for(const f of ['search',...fields])$(f).value='';syncLocations();update();}
function renderCards(){const pages=Math.max(1,Math.ceil(state.filtered.length/state.pageSize));state.page=Math.min(state.page,pages);$('cards').innerHTML=state.filtered.slice((state.page-1)*state.pageSize,state.page*state.pageSize).map(r=>`<button class="heritage-card" data-id="${esc(r.id)}" aria-label="查看${esc(r.name)}详情"><span class="list-marker"><svg><use href="#map-icon"/></svg></span><div><h3>${esc(r.name)}</h3><p>${esc(r.era)} · ${esc(shortCategory(r.category))}<br>${esc([r.province,r.city==='待核对'?'':r.city,r.county==='待核对'?'':r.county].filter((v,i,a)=>v&&a.indexOf(v)===i).join(' · '))}${r.coordinates?'':' · 待定位'}</p></div><span>›</span></button>`).join('');$('empty').hidden=state.filtered.length>0;$('page-status').textContent=`${state.page} / ${pages}`;$('prev').disabled=state.page<=1;$('next').disabled=state.page>=pages;$('cards').querySelectorAll('[data-id]').forEach(el=>el.addEventListener('click',()=>showDetail(el.dataset.id)));}
function renderMap(){if(!state.chart)return;const p=$('province').value;let mapName='china',bounds;const points=state.filtered.filter(r=>r.coordinates);if(p){const rid=state.rows.find(r=>r.province===p)?.region_id,feature=state.china.features.find(f=>String(f.properties.adcode)===rid);if(feature){mapName='selected';echarts.registerMap(mapName,{type:'FeatureCollection',features:[feature]});}if($('city').value&&points.length){const xs=points.map(r=>r.coordinates[0]),ys=points.map(r=>r.coordinates[1]);let x1=Math.min(...xs),x2=Math.max(...xs),y1=Math.min(...ys),y2=Math.max(...ys),dx=Math.max((x2-x1)*.3,.12),dy=Math.max((y2-y1)*.3,.12);bounds=[[x1-dx,y2+dy],[x2+dx,y1-dy]];}}
const groups=new Map();for(const r of state.filtered){if(!groups.has(r.region_id))groups.set(r.region_id,{name:r.province,count:0});groups.get(r.region_id).count++;}const aggregate=!p&&state.filtered.length>30,bubbleData=[...groups].map(([id,r])=>{const f=state.china.features.find(f=>String(f.properties.adcode)===id),c=f?.properties.centroid||f?.properties.center;return c?{name:r.name,value:[...c,r.count],province:r.name}:null;}).filter(Boolean);
state.chart.setOption({animationDuration:350,animationDurationUpdate:350,tooltip:{show:false},geo:{map:mapName,roam:true,zoom:1,scaleLimit:{min:.7,max:12},boundingCoords:bounds,layoutCenter:['50%',p?'51%':'49%'],layoutSize:p?'85%':'94%',label:{show:!aggregate,fontSize:10,color:'#7c8e70'},itemStyle:{areaColor:'#f1f3e2',borderColor:'#c1cfb2',borderWidth:.7,shadowColor:'#718a6230',shadowBlur:12},emphasis:{label:{show:false},itemStyle:{areaColor:'#d8e3c8'}},select:{disabled:true}},series:[aggregate?{type:'scatter',coordinateSystem:'geo',symbol:'circle',symbolSize:val=>Math.min(29,17+Math.sqrt(val[2])*.5),label:{show:true,formatter:p=>String(p.value[2]),color:'#3f6649',fontSize:9,fontWeight:600},labelLayout:{hideOverlap:true},itemStyle:{color:'#ffffffd9',borderColor:'#fff',borderWidth:1.2,shadowBlur:8,shadowColor:'#39572a2b'},emphasis:{scale:1.2},data:bubbleData}:{type:'scatter',coordinateSystem:'geo',symbolSize:points.length<40?12:7,itemStyle:{color:'#5a8360',borderColor:'#ffffffed',borderWidth:1.5,shadowColor:'#305b3540',shadowBlur:5},emphasis:{scale:1.4,itemStyle:{color:'#b77f53'}},data:points.map(r=>({name:r.name,id:r.id,value:r.coordinates}))}]},true);}
function openSheet(id){for(const d of document.querySelectorAll('dialog[open]'))d.close();$(id).showModal();}
function showDetail(id){const r=state.rows.find(r=>r.id===id);if(!r)return;const description=state.meta.research.featured_descriptions?.find(x=>x.name===r.name);$('detail-body').innerHTML=`<span class="detail-type">全国重点文物保护单位 · 第${numbers[r.batch-1]}批</span><h2 class="detail-title">${esc(r.name)}</h2>${description?`<p class="detail-description">${esc(description.description)}</p>`:''}<div class="tags">${[r.category,r.era].map(t=>`<span class="tag">${esc(shortCategory(t))}</span>`).join('')}</div><dl class="detail-facts"><dt>所在地</dt><dd>${esc([r.province,r.city,r.county].join(' · '))}</dd><dt>原始地址</dt><dd>${esc(r.address||'未注明')}</dd><dt>位置</dt><dd>${r.coordinates?'第三方参考点位':'待定位 · 暂未匹配可靠坐标'}</dd></dl><div class="detail-actions"><button id="locate-record" class="primary" ${r.coordinates?'':'disabled'}>在地图上查看</button><a class="secondary" href="${esc(r.source)}" target="_blank" rel="noopener" style="text-align:center">原文来源 ↗</a></div><div class="detail-foot"><span>${description?`<a href="${esc(description.source)}" target="_blank" rel="noopener">介绍来源 ↗</a>`:'八批名录 · 2026.11 核对'}</span><button id="share-record">分享条目 ↗</button></div><details class="more-info"><summary>更多信息与定位说明</summary><p>原始类型：${esc(r.category_original)}<br>时代标签：${esc(r.tags.join('、')||'未提取')}<br>${r.aliases?.length?'历史名称：'+esc(r.aliases.join('、'))+'<br>':''}${r.coordinates?`${esc(r.coordinate_source)}<br>坐标：${r.coordinates.map(n=>n.toFixed(5)).join(', ')}`:''}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<p>参考点位不等于入口、保护范围或全部子项；市县由地址匹配，历史地名可能仍需核对。</p></details>`;openSheet('detail');$('locate-record').addEventListener('click',()=>{reset();$('province').value=r.province;syncLocations();if(r.city!=='待核对'){$('city').value=r.city;syncLocations();}if(r.county!=='待核对')$('county').value=r.county;$('search').value=r.name;update();$('detail').close();});$('share-record').addEventListener('click',async()=>{const url=new URL(location.href);url.hash=`unit=${encodeURIComponent(r.id)}`;try{await navigator.clipboard.writeText(url.href);toast('条目链接已复制');}catch{history.replaceState(null,'',url);toast('请复制地址栏链接');}});}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
async function main(){try{const [data,china]=await Promise.all(['data/heritage.json','data/china.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw new Error('数据加载失败');return r.json();}));state.rows=data.rows;state.meta=data.meta;state.china=china;options($('province'),sortNames(state.rows.map(r=>r.province)),'全国');options($('category'),categories,'全部类型');options($('era'),eras,'全部时代');$('batch').innerHTML='<option value="">全部批次</option>'+numbers.split('').map((n,i)=>`<option value="${i+1}">第${n}批</option>`).join('');const initialId=location.hash.startsWith('#unit=')?decodeURIComponent(location.hash.slice(6)):null,params=new URLSearchParams(location.search);for(const f of ['search','province','category','era','batch'])if(params.has(f))$(f).value=params.get(f);syncLocations();if(params.has('city'))$('city').value=params.get('city');syncLocations();if(params.has('county'))$('county').value=params.get('county');$('coverage-note').textContent='整理 5,058 条名录，覆盖 31 个省级行政区。5,016 条有参考点位，42 条待定位。4,756 条可解析到城市，3,709 条可解析到单一区县。';$('batches').innerHTML=data.meta.research.batches.map(b=>`<a class="batch-link" href="${esc(b.source)}" target="_blank" rel="noopener"><span>第${numbers[b.batch-1]}批 · ${b.date}</span><span>${b.count.toLocaleString()} 处 ↗</span></a>`).join('');
if(window.echarts){echarts.registerMap('china',china);state.chart=echarts.init($('map'));state.chart.on('click',p=>{if(p.data?.id){showDetail(p.data.id);return;}let province=p.data?.province;if(!province&&p.componentType==='geo'){const feature=china.features.find(f=>f.properties.name===p.name);province=state.rows.find(r=>r.region_id===String(feature?.properties.adcode))?.province;}if(province){$('province').value=province;$('city').value='';$('county').value='';syncLocations();update();}});new ResizeObserver(()=>state.chart.resize()).observe($('map'));}else throw new Error('地图组件加载失败，请刷新重试');
for(const f of fields)$(f).addEventListener('change',()=>{if(f==='province'){$('city').value='';$('county').value='';syncLocations();}if(f==='city'){$('county').value='';syncLocations();}update();});let timer;$('search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(update,180);});for(const id of ['filter-open','region-open','type-open'])$(id).addEventListener('click',()=>openSheet('filters'));for(const id of ['info-open','source-open'])$(id).addEventListener('click',()=>openSheet('info'));$('list-open').addEventListener('click',()=>openSheet('results'));$('filters-apply').addEventListener('click',()=>$('filters').close());for(const id of ['filters-clear','reset','empty-reset'])$(id).addEventListener('click',reset);for(const d of document.querySelectorAll('dialog')){d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});}for(const [id,step] of [['prev',-1],['next',1]])$(id).addEventListener('click',()=>{state.page+=step;renderCards();$('results').scrollTop=0;});for(const [id,factor] of [['zoom-in',1.3],['zoom-out',1/1.3]])$(id).addEventListener('click',()=>{const zoom=state.chart.getOption().geo[0].zoom;state.chart.setOption({geo:{zoom:Math.max(.7,Math.min(12,zoom*factor))}});});$('map-reset').addEventListener('click',renderMap);$('loading').hidden=true;update();if(initialId)showDetail(initialId);window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#unit='))showDetail(decodeURIComponent(location.hash.slice(6)));});
}catch(error){$('loading').textContent='地图暂未加载，请刷新重试';console.error(error);}}
main();
